SELECT p.gender, p.age, s.stay_id, s.hadm_id, s.los, i.imaging_id, i.imaging_type, i.imaging_date, i.imaging_time, percentile_cont(0.25) within GROUP (ORDER BY s.los) AS p25_los, percentile_cont(0.75) within GROUP (ORDER BY s.los) AS p75_los FROM patients p JOIN stay s ON p.subject_id = s.subject_id JOIN icustays i ON s.stay_id = i.stay_id WHERE p.gender = 'F' AND p.age BETWEEN 44 AND 54 AND i.imaging_type = 'CT' GROUP BY p.gender, p.age, s.stay_id, s.hadm_id, s.los, i.imaging_id, i.imaging_type, i.imaging_date, i.imaging_time ORDER BY p.gender, p.age, s.stay_id, s.hadm_id, s.los, i.imaging_id, i.imaging_type, i.imaging_date, i.imaging_time NULLS LAST;